    let ident = &ast.ident;
    let generics = if deflated {
        parse_quote!(<'r, 'a>)
    } else {
        ast.generics.clone()
    };

    let (treyt, leftparen, rightparen) = idents(deflated);
    let gen = quote! {
        impl#generics #treyt#generics for #ident #generics {
            fn lpar(&self) -> &Vec<#leftparen#generics> {
