            fn rpar(&self) -> &Vec<#rightparen#generics> {
                &self.rpar
            }
            fn with_parens(self, left: #leftparen#generics, right: #rightparen#generics) -> Self {
                let mut lpar = self.lpar;
                let mut rpar = self.rpar;
