/// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
pub(crate) fn remove_unused_positional_arguments_from_format_call(
    &self,
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let source_code = locator.slice(call);
    transform_expression(source_code, stylist, |expression| {
        let mut expression = match expression {
            Expression::Call(mut call) => {
                // If all arguments will be removed, replace the call with the
                // object on which `format` was called (e.g.,
                // `"Hello".format("world")` becomes `"Hello"`).
                if call.args.iter().enumerate().all(|(index, arg)| {
                    arg.keyword.is_none() && unused_arguments.contains(&index)
                }) {
                    let lpar = std::mem::take(&mut call.lpar);
                    let rpar = std::mem::take(&mut call.rpar);
                    let mut receiver = match *call.func {
                        Expression::Attribute(attribute) => *attribute.value,
                        receiver => receiver,
                    };
                    // Preserve any parentheses that surrounded the call.
                    for (left, right) in lpar.into_iter().zip(rpar) {
                        receiver = receiver.with_parens(left, right);
                    }
                    return Ok(receiver);
                }

                // Remove any unused arguments.
                let mut index = 0;
                call.args.retain(|_| {
                    let is_unused = unused_arguments.contains(&index);
                    index += 1;
                    !is_unused
                });

                Expression::Call(call)
            }
            expression => {
                match_call_mut(&mut expression.clone())?;
                expression
            }
        };
        Ok(expression)
    })
    .map(|output| Edit::range_replacement(output, call.range()))
}

